package com.codepilot1c.core.tools.development;
import java.util.concurrent.CompletableFuture;import com.codepilot1c.core.tools.*;import com.codepilot1c.core.edt.development.*;
@ToolMeta(name="edt_agent_metrics",category="workspace",tags={"read-only","workspace","edt"})
public final class EdtAgentMetricsTool extends AbstractTool {
 private java.util.Map<String,Object> metrics(){var value=new java.util.LinkedHashMap<String,Object>(AgentMetrics.snapshot());value.put("ui",UiLagMonitor.snapshot());return value;}
 public String getDescription(){return "Read process-local per-tool call counts, UTF-8 JSON request/response bytes, wall time and failures. Includes bounded UI heartbeat lag events and operation names/stacks. No payloads retained. Compare snapshots; bytes are not model tokens. Current metrics request is counted after its response. action=baseline stores a bounded process-local counter snapshot and returns baseline_id without all tool rows; action=changes with baseline_id returns only changed counters. Baselines last1h, at most16, lost on restart; no reset or mutation of work. Deltas include metrics/discovery overhead. Empty arguments keep the previous full snapshot including UI lag.";}
 public String getParameterSchema(){return AgentResponses.schema("{\"type\":\"object\",\"additionalProperties\":false,\"properties\":{\"action\":{\"enum\":[\"snapshot\",\"baseline\",\"changes\"],\"default\":\"snapshot\"},\"baseline_id\":{\"type\":\"string\",\"pattern\":\"^metrics-[a-f0-9-]{36}$\"}}}");}
 protected CompletableFuture<ToolResult> doExecute(ToolParameters p){try{String action=p.getRaw().containsKey("action")?p.requireString("action"):"snapshot";if(!action.equals("changes")&&p.getRaw().containsKey("baseline_id"))throw new IllegalArgumentException("baseline_id requires action=changes");var value=switch(action){case "snapshot"->metrics();case "baseline"->AgentMetrics.baseline();case "changes"->AgentMetrics.changes(p.requireString("baseline_id"));default->throw new IllegalArgumentException("Unknown metrics action");};return CompletableFuture.completedFuture(AgentResponses.success(value,p.getRaw()));}catch(Exception e){return CompletableFuture.completedFuture(ToolResult.failure("edt_agent_metrics: "+e.getMessage()));}}
}
